function fmt(n) {
  if (!Number.isFinite(n)) return String(n);
  const a = Math.abs(n);
  if ((a && a < 0.001) || a >= 1e5) return n.toExponential(3).replace(/\.0+e/, 'e');
  return Number(n.toPrecision(5)).toString();
}
function rotate(a, n) { const k = n % a.length; return a.slice(k).concat(a.slice(0, k)); }
function numericOptions(value, unit, seed) {
  const values = [value, value * 2, value / 2, value === 0 ? 1 : -value].map(fmt);
  const unique = [...new Set(values)];
  while (unique.length < 4) unique.push(fmt(value + unique.length + 1));
  return rotate(unique.slice(0, 4).map(x => `${x}${unit ? ` ${unit}` : ''}`), seed);
}
