function buildSubtopic(ch, sub, ci, si) {
  const questions = sub.items.flatMap((item,i) => item.kind === 'numerical' ? numericalQuestions(ch,sub,item,i) : conceptQuestions(ch,sub,item,i));
  if (questions.length !== 40) throw new Error(`${ch.name}/${sub.name}: ${questions.length}`);
  return questions.map((q,i) => ({ ...q, id: `NEET-CHEM11-${String(ci+1).padStart(2,'0')}-${String(si+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`, questionNumber: i+1, difficulty: i < 8 ? 'Foundation' : i < 32 ? 'NEET Standard' : 'Challenge', estimatedTime: i < 8 ? '45-60 s' : i < 32 ? q.estimatedTime : '120-150 s' }));
}

